fun nextGreater(nums: IntArray): IntArray {
    val result = IntArray(nums.size) { -1 }         // -1 means no greater element
    val stack = ArrayDeque<Int>()                    // stores indices
    for (i in nums.indices) {
        while (stack.isNotEmpty() && nums[i] > nums[stack.last()]) {
            val idx = stack.removeLast()
            result[idx] = nums[i]                    // nums[i] is the next greater of idx
        }
        stack.addLast(i)
    }
    return result
}
// Time: O(n)   Space: O(n)

fun nextSmaller(nums: IntArray): IntArray {
    val result = IntArray(nums.size) { -1 }
    val stack = ArrayDeque<Int>()
    for (i in nums.indices) {
        while (stack.isNotEmpty() && nums[i] < nums[stack.last()]) {
            val idx = stack.removeLast()
            result[idx] = nums[i]
        }
        stack.addLast(i)
    }
    return result
}
// Time: O(n)   Space: O(n)

fun previousSmaller(nums: IntArray): IntArray {
    val result = IntArray(nums.size) { -1 }
    val stack = ArrayDeque<Int>()
    for (i in nums.indices) {
        while (stack.isNotEmpty() && nums[stack.last()] >= nums[i]) {
            stack.removeLast()                       // these cannot be the answer for i
        }
        if (stack.isNotEmpty()) result[i] = nums[stack.last()]
        stack.addLast(i)
    }
    return result
}
// Time: O(n)   Space: O(n)
// After popping, the top of the stack is the nearest smaller element on the left

fun dailyTemperatures(temps: IntArray): IntArray {
    val answer = IntArray(temps.size)
    val stack = ArrayDeque<Int>()
    for (i in temps.indices) {
        while (stack.isNotEmpty() && temps[i] > temps[stack.last()]) {
            val prev = stack.removeLast()
            answer[prev] = i - prev                  // days to wait
        }
        stack.addLast(i)
    }
    return answer
}
// Time: O(n)   Space: O(n)

fun nextGreaterElement(nums1: IntArray, nums2: IntArray): IntArray {
    val nextGreater = HashMap<Int, Int>()
    val stack = ArrayDeque<Int>()
    for (x in nums2) {
        while (stack.isNotEmpty() && x > stack.last()) {
            nextGreater[stack.removeLast()] = x
        }
        stack.addLast(x)
    }
    return IntArray(nums1.size) { nextGreater[nums1[it]] ?: -1 }
}
// Time: O(n + m)   Space: O(n)

fun nextGreaterCircular(nums: IntArray): IntArray {
    val n = nums.size
    val result = IntArray(n) { -1 }
    val stack = ArrayDeque<Int>()
    for (i in 0 until 2 * n) {                       // go around twice
        val x = nums[i % n]
        while (stack.isNotEmpty() && x > nums[stack.last()]) {
            result[stack.removeLast()] = x
        }
        if (i < n) stack.addLast(i)                  // push only in the first pass
    }
    return result
}
// Time: O(n)   Space: O(n)

fun largestRectangleArea(heights: IntArray): Int {
    val stack = ArrayDeque<Int>()                    // increasing heights (indices)
    var best = 0
    for (i in 0..heights.size) {
        val h = if (i == heights.size) 0 else heights[i]      // sentinel 0 flushes the stack
        while (stack.isNotEmpty() && h < heights[stack.last()]) {
            val height = heights[stack.removeLast()]
            val left = if (stack.isEmpty()) -1 else stack.last()
            val width = i - left - 1                           // between left and i
            best = maxOf(best, height * width)
        }
        stack.addLast(i)
    }
    return best
}
// Time: O(n)   Space: O(n)

fun maximalRectangle(matrix: Array<CharArray>): Int {
    if (matrix.isEmpty()) return 0
    val cols = matrix[0].size
    val heights = IntArray(cols)
    var best = 0
    for (row in matrix) {
        for (c in 0 until cols) {
            heights[c] = if (row[c] == '1') heights[c] + 1 else 0
        }
        best = maxOf(best, largestRectangleArea(heights))   // reuse the histogram solution
    }
    return best
}
// Time: O(rows * cols)   Space: O(cols)

fun trap(height: IntArray): Int {
    val stack = ArrayDeque<Int>()
    var water = 0
    for (i in height.indices) {
        while (stack.isNotEmpty() && height[i] > height[stack.last()]) {
            val bottom = stack.removeLast()
            if (stack.isEmpty()) break
            val left = stack.last()
            val width = i - left - 1
            val bounded = minOf(height[i], height[left]) - height[bottom]
            water += width * bounded
        }
        stack.addLast(i)
    }
    return water
}
// Time: O(n)   Space: O(n)
// The two pointers version uses O(1) space

class StockSpanner {
    private val stack = ArrayDeque<IntArray>()        // [price, span]

    fun next(price: Int): Int {
        var span = 1
        while (stack.isNotEmpty() && stack.last()[0] <= price) {
            span += stack.removeLast()[1]             // absorb smaller or equal days
        }
        stack.addLast(intArrayOf(price, span))
        return span
    }
}
// Amortized O(1) per call   Space: O(n)

fun removeKdigits(num: String, k: Int): String {
    val stack = StringBuilder()
    var remaining = k
    for (c in num) {
        while (remaining > 0 && stack.isNotEmpty() && stack.last() > c) {
            stack.deleteCharAt(stack.length - 1)      // drop a bigger digit before a smaller one
            remaining--
        }
        stack.append(c)
    }
    while (remaining > 0 && stack.isNotEmpty()) {     // still need to remove from the end
        stack.deleteCharAt(stack.length - 1)
        remaining--
    }
    val result = stack.toString().trimStart('0')      // remove leading zeros
    return if (result.isEmpty()) "0" else result
}
// Time: O(n)   Space: O(n)

fun removeDuplicateLetters(s: String): String {
    val last = IntArray(26)
    for (i in s.indices) last[s[i] - 'a'] = i          // last position of each letter
    val inStack = BooleanArray(26)
    val stack = StringBuilder()
    for (i in s.indices) {
        val c = s[i]
        if (inStack[c - 'a']) continue
        while (stack.isNotEmpty() && stack.last() > c && last[stack.last() - 'a'] > i) {
            inStack[stack.last() - 'a'] = false
            stack.deleteCharAt(stack.length - 1)
        }
        stack.append(c)
        inStack[c - 'a'] = true
    }
    return stack.toString()
}
// Time: O(n)   Space: O(1) (26 letters)

fun sumSubarrayMins(arr: IntArray): Int {
    val mod = 1_000_000_007L
    val n = arr.size
    val left = IntArray(n)      // distance to previous smaller element
    val right = IntArray(n)     // distance to next smaller-or-equal element
    val stack = ArrayDeque<Int>()
    for (i in 0 until n) {
        while (stack.isNotEmpty() && arr[stack.last()] > arr[i]) stack.removeLast()
        left[i] = if (stack.isEmpty()) i + 1 else i - stack.last()
        stack.addLast(i)
    }
    stack.clear()
    for (i in n - 1 downTo 0) {
        while (stack.isNotEmpty() && arr[stack.last()] >= arr[i]) stack.removeLast()
        right[i] = if (stack.isEmpty()) n - i else stack.last() - i
        stack.addLast(i)
    }
    var total = 0L
    for (i in 0 until n) {
        total = (total + arr[i].toLong() * left[i] * right[i]) % mod
    }
    return total.toInt()
}
// Time: O(n)   Space: O(n)
// Each element is the minimum of left[i] * right[i] subarrays
// One side uses strict and the other non-strict comparison to avoid double counting

fun asteroidCollision(asteroids: IntArray): IntArray {
    val stack = ArrayDeque<Int>()
    for (a in asteroids) {
        var alive = true
        while (alive && a < 0 && stack.isNotEmpty() && stack.last() > 0) {
            val top = stack.last()
            when {
                top < -a -> stack.removeLast()           // top explodes, keep checking
                top == -a -> { stack.removeLast(); alive = false }   // both explode
                else -> alive = false                    // new asteroid explodes
            }
        }
        if (alive) stack.addLast(a)
    }
    return stack.toIntArray()
}
// Time: O(n)   Space: O(n)

fun find132pattern(nums: IntArray): Boolean {
    val stack = ArrayDeque<Int>()
    var third = Int.MIN_VALUE                           // the '2' in the 132 pattern
    for (i in nums.indices.reversed()) {
        if (nums[i] < third) return true                // found the '1'
        while (stack.isNotEmpty() && stack.last() < nums[i]) {
            third = stack.removeLast()                  // largest popped value becomes '2'
        }
        stack.addLast(nums[i])
    }
    return false
}
// Time: O(n)   Space: O(n)
